Complexity and Measurement:
Growth is a shape, not a stopwatch. Count the operations for several sizes and watch how the count scales:

```js
function opsFor(n) {
  let ops = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i; j < n; j++) ops++;
  }
  return ops;   // n(n+1)/2 — O(n^2)
}
for (const n of [10, 20, 40]) console.log(n, opsFor(n), opsFor(n) / (n * n));
```

Once you have a closed form you can predict a size you would never run, which is the point of the analysis:

```js
const quadratic = (n) => (n * (n + 1)) / 2;
const linear = (n) => n;
const logarithmic = (n) => Math.ceil(Math.log2(n + 1));
for (const n of [1e3, 1e4, 1e5]) {
  console.log(n, { quadratic: quadratic(n), linear: linear(n), log: logarithmic(n) });
}
```

Amortised cost is the honest label for an occasional resize: one call is expensive, but spread across the calls that filled the array it is constant:

```js
function amortisedPush(n) {
  let size = 1, copies = 0, pushes = 0;
  const push = () => {
    pushes++;
    if (pushes > size) { copies += size; size *= 2; }
  };
  for (let i = 0; i < n; i++) push();
  return copies / n;   // approaches 1 — O(1) amortised
}
console.log(amortisedPush(1_000_000));
```

When you do time real code, warm it up, run the body enough times to be measurable, and take the median rather than a single reading:

```js
function bench(label, fn, iters = 1_000_000) {
  fn(); // warm up the JIT
  const times = [];
  for (let r = 0; r < 5; r++) {
    const t0 = performance.now();
    for (let i = 0; i < iters; i++) fn();
    times.push((performance.now() - t0) / iters);
  }
  times.sort((a, b) => a - b);
  console.log(label, (times[2] * 1e6).toFixed(1), 'ns/op');
}
bench('increment', () => { let x = 0; x++; });
```

A benchmark only means something alongside a correctness check, so prove the fast path and the simple path agree before you trust the numbers:

```js
const fast = (xs) => xs.reduce((a, b) => a + b, 0);
const simple = (xs) => { let s = 0; for (const x of xs) s += x; return s; };
const data = Array.from({ length: 1000 }, (_, i) => i);
console.log(fast(data), simple(data), fast(data) === simple(data));
```

Stacks, Queues and Sequences:
An array is a stack for free; a queue is not, because `shift` moves every element that follows:

```js
const stack = [];
stack.push(1); stack.push(2);
console.log(stack.pop(), stack.length);   // 2 1

const queue = [];
queue.push(1); queue.push(2);
console.log(queue.shift());               // 1 — O(n)
```

A ring buffer gives O(1) enqueue and dequeue with a fixed capacity:

```js
class RingBuffer {
  #buf; #head = 0; #size = 0;
  constructor(capacity) { this.#buf = new Array(capacity); }
  push(value) {
    if (this.#size === this.#buf.length) throw new Error('full');
    this.#buf[(this.#head + this.#size) % this.#buf.length] = value;
    this.#size++;
  }
  shift() {
    if (!this.#size) return undefined;
    const value = this.#buf[this.#head];
    this.#buf[this.#head] = undefined;
    this.#head = (this.#head + 1) % this.#buf.length;
    this.#size--;
    return value;
  }
  get length() { return this.#size; }
}
const q = new RingBuffer(3);
q.push('a'); q.push('b'); q.push('c');
console.log(q.shift(), q.shift(), q.length);   // a b 1
```

A linked list is worth writing once so the pointer juggling is concrete:

```js
class LinkedList {
  #head = null; #tail = null; #size = 0;
  push(value) {
    const node = { value, next: null };
    if (this.#tail) this.#tail.next = node; else this.#head = node;
    this.#tail = node; this.#size++;
    return this;
  }
  get head() { return this.#head; }
  get size() { return this.#size; }
  *[Symbol.iterator]() {
    for (let node = this.#head; node; node = node.next) yield node.value;
  }
}
const list = new LinkedList();
list.push(1).push(2).push(3);
console.log([...list], list.size);   // [ 1, 2, 3 ] 3
```

Reversing in place and detecting a cycle with fast and slow pointers are the two canonical list exercises:

```js
function reverse(head) {
  let prev = null;
  for (let node = head; node; ) {
    const next = node.next; node.next = prev; prev = node; node = next;
  }
  return prev;
}
const nodes = [1, 2, 3].map((value) => ({ value, next: null }));
nodes.forEach((node, i) => { node.next = nodes[i + 1] ?? null; });
console.log(reverse(nodes[0]).value);   // 3

function hasCycle(head) {
  let slow = head, fast = head;
  while (fast && fast.next) {
    slow = slow.next; fast = fast.next.next;
    if (slow === fast) return true;
  }
  return false;
}
console.log(hasCycle({ value: 1, next: { value: 2, next: null } }));   // false
```

A monotonic stack answers questions about the next greater element in a single pass:

```js
function nextGreater(values) {
  const out = new Array(values.length).fill(-1);
  const stack = [];   // indices, values decreasing
  for (let i = 0; i < values.length; i++) {
    while (stack.length && values[stack.at(-1)] < values[i]) out[stack.pop()] = values[i];
    stack.push(i);
  }
  return out;
}
console.log(nextGreater([2, 1, 3, 4, 0]));   // [ 3, 3, 4, -1, -1 ]
```

Hash Tables, Sets and Maps:
A map is only as good as its keys: object keys stringify, so two distinct objects collide, and a mutating key disappears:

```js
const m = new Map();
const key = { id: 1 };
m.set(key, 'a');
m.set({ id: 1 }, 'b');
console.log(m.size, m.get(key));   // 2 'a'

const bad = {};
bad[1] = 'num'; bad['1'] = 'str';
console.log(Object.keys(bad).length, bad[1]);   // 1 'str'
```

A tiny hash table shows why collisions need buckets rather than overwrites:

```js
class HashMap {
  #buckets; #n = 0;
  constructor(size = 16) { this.#buckets = Array.from({ length: size }, () => []); }
  #index(key) {
    const s = String(key);
    let h = 2166136261;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
    return (h >>> 0) % this.#buckets.length;
  }
  set(key, value) {
    const bucket = this.#buckets[this.#index(key)];
    const found = bucket.find((entry) => entry[0] === key);
    if (found) { found[1] = value; return; }
    bucket.push([key, value]); this.#n++;
    if (this.#n > this.#buckets.length * 0.75) this.#grow();
  }
  get(key) { return this.#buckets[this.#index(key)].find((entry) => entry[0] === key)?.[1]; }
  #grow() {
    const old = this.#buckets;
    this.#buckets = Array.from({ length: old.length * 2 }, () => []);
    const entries = old.flat(); this.#n = 0;
    for (const [k, v] of entries) this.set(k, v);
  }
}
const hm = new HashMap(4);
for (let i = 0; i < 10; i++) hm.set('k' + i, i * i);
console.log(hm.get('k7'), hm.get('missing'));   // 49 undefined
```

A set answers membership and deduplicates in one structure, and an LRU cache combines a Map's insertion order with a size cap:

```js
class LRU {
  #map = new Map(); #max;
  constructor(max) { this.#max = max; }
  get(key) {
    if (!this.#map.has(key)) return undefined;
    const value = this.#map.get(key);
    this.#map.delete(key); this.#map.set(key, value);   // refresh recency
    return value;
  }
  set(key, value) {
    this.#map.delete(key);
    this.#map.set(key, value);
    if (this.#map.size > this.#max) this.#map.delete(this.#map.keys().next().value);
  }
}
const lru = new LRU(2);
lru.set('a', 1); lru.set('b', 2); lru.get('a'); lru.set('c', 3);
console.log(lru.get('b'), lru.get('a'));   // undefined 1
```

Counting and grouping with a Map keeps insertion order and never coerces the key:

```js
const words = ['a', 'b', 'a', 'c', 'b', 'a'];
const counts = new Map();
for (const word of words) counts.set(word, (counts.get(word) ?? 0) + 1);
console.log([...counts]);   // [ [ 'a', 3 ], [ 'b', 2 ], [ 'c', 1 ] ]

const byWord = new Map();
for (const word of words) byWord.set(word, [...(byWord.get(word) ?? []), word.length]);
console.log(byWord.get('a'));   // [ 1, 1, 1 ]
```

Trees, Heaps and Tries:
A binary search tree gives ordered traversal for free, provided you never recurse deeper than the stack allows:

```js
class BST {
  #root = null;
  insert(value) {
    const node = { value, left: null, right: null };
    if (!this.#root) { this.#root = node; return; }
    for (let cur = this.#root; ; ) {
      if (value < cur.value) { if (!cur.left) { cur.left = node; return; } cur = cur.left; }
      else { if (!cur.right) { cur.right = node; return; } cur = cur.right; }
    }
  }
  *inOrder() {
    const stack = [];
    for (let cur = this.#root; cur || stack.length; ) {
      while (cur) { stack.push(cur); cur = cur.left; }
      cur = stack.pop(); yield cur.value; cur = cur.right;
    }
  }
  has(value) {
    for (let cur = this.#root; cur; ) {
      if (value === cur.value) return true;
      cur = value < cur.value ? cur.left : cur.right;
    }
    return false;
  }
  height() {
    const walk = (node) => (node ? 1 + Math.max(walk(node.left), walk(node.right)) : 0);
    return walk(this.#root);
  }
}
const tree = new BST();
for (const v of [5, 3, 8, 1, 4, 7, 9]) tree.insert(v);
console.log([...tree.inOrder()], tree.has(4), tree.height());   // [1,3,4,5,7,8,9] true 3
```

A binary heap is the array-backed priority queue behind schedulers; sift-up and sift-down keep the invariant:

```js
class MinHeap {
  #a = [];
  get size() { return this.#a.length; }
  push(value) {
    const a = this.#a; a.push(value);
    for (let i = a.length - 1; i > 0; ) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  pop() {
    const a = this.#a;
    if (!a.length) return undefined;
    const top = a[0], last = a.pop();
    if (a.length) {
      a[0] = last;
      for (let i = 0; ; ) {
        const l = 2 * i + 1, r = l + 1;
        let smallest = i;
        if (l < a.length && a[l] < a[smallest]) smallest = l;
        if (r < a.length && a[r] < a[smallest]) smallest = r;
        if (smallest === i) break;
        [a[i], a[smallest]] = [a[smallest], a[i]]; i = smallest;
      }
    }
    return top;
  }
}
const heap = new MinHeap();
for (const v of [5, 1, 8, 3]) heap.push(v);
const out = []; while (heap.size) out.push(heap.pop());
console.log(out);   // [ 1, 3, 5, 8 ]
```

With a heap, heap sort and the classic `n` smallest problem are a few lines:

```js
const nSmallest = (values, n) => {
  const heap = new MinHeap();
  for (const value of values) heap.push(value);
  return Array.from({ length: n }, () => heap.pop());
};
console.log(nSmallest([9, 4, 7, 1, 8, 2], 3));   // [ 1, 2, 4 ]
```

A trie turns prefix search into a walk, which is how autocomplete stays fast as the word list grows:

```js
class Trie {
  #root = {};
  insert(word) {
    let node = this.#root;
    for (const ch of word) node = node[ch] ??= {};
    node['$'] = true;
  }
  #walk(prefix) {
    let node = this.#root;
    for (const ch of prefix) { node = node[ch]; if (!node) return null; }
    return node;
  }
  has(word) { return Boolean(this.#walk(word)?.['$']); }
  withPrefix(prefix) {
    const start = this.#walk(prefix);
    const out = [];
    const visit = (node, path) => {
      if (node['$']) out.push(path);
      for (const [ch, child] of Object.entries(node)) if (ch !== '$') visit(child, path + ch);
    };
    if (start) visit(start, prefix);
    return out;
  }
}
const trie = new Trie();
for (const word of ['car', 'care', 'cart', 'core']) trie.insert(word);
console.log(trie.withPrefix('car'), trie.has('care'));   // [ 'car', 'care', 'cart' ] true
```

Graphs, Sorting and Searching:
An adjacency list plus breadth-first search finds the shortest number of hops, while depth-first search answers reachability:

```js
const graph = new Map([
  ['a', ['b', 'c']], ['b', ['d']], ['c', ['d', 'e']], ['d', ['e']], ['e', []],
]);

function bfs(start, goal) {
  const queue = [[start]];
  const seen = new Set([start]);
  while (queue.length) {
    const path = queue.shift();
    if (path.at(-1) === goal) return path;
    for (const next of graph.get(path.at(-1)) ?? []) {
      if (!seen.has(next)) { seen.add(next); queue.push([...path, next]); }
    }
  }
  return null;
}
console.log(bfs('a', 'e'));   // [ 'a', 'c', 'e' ]

function dfs(node, seen = new Set()) {
  seen.add(node);
  for (const next of graph.get(node) ?? []) if (!seen.has(next)) dfs(next, seen);
  return seen;
}
console.log([...dfs('a')].sort());   // [ 'a', 'b', 'c', 'd', 'e' ]
```

A topological order exists only without cycles, and consuming in-degrees proves both at once:

```js
function topo(nodes, edges) {
  const indegree = new Map(nodes.map((n) => [n, 0]));
  const out = new Map(nodes.map((n) => [n, []]));
  for (const [from, to] of edges) { out.get(from).push(to); indegree.set(to, indegree.get(to) + 1); }
  const ready = nodes.filter((n) => indegree.get(n) === 0);
  const order = [];
  while (ready.length) {
    const node = ready.shift(); order.push(node);
    for (const next of out.get(node)) {
      indegree.set(next, indegree.get(next) - 1);
      if (indegree.get(next) === 0) ready.push(next);
    }
  }
  return order.length === nodes.length ? order : null;   // null means a cycle
}
console.log(topo(['a', 'b', 'c', 'd'], [['a', 'b'], ['a', 'c'], ['b', 'd'], ['c', 'd']]));
```

Dijkstra relaxes each edge only when it finds a strictly shorter route to a node:

```js
function dijkstra(adj, start) {
  const dist = new Map([...adj.keys()].map((node) => [node, Infinity]));
  dist.set(start, 0);
  const queue = [[0, start]];
  while (queue.length) {
    queue.sort((x, y) => x[0] - y[0]);
    const [d, node] = queue.shift();
    if (d > dist.get(node)) continue;
    for (const [next, weight] of adj.get(node)) {
      const nd = d + weight;
      if (nd < dist.get(next)) { dist.set(next, nd); queue.push([nd, next]); }
    }
  }
  return dist;
}
console.log(dijkstra(new Map([
  ['a', [['b', 1], ['c', 4]]], ['b', [['c', 2], ['d', 5]]], ['c', [['d', 1]]], ['d', []],
]), 'a'));
```

Sorting: merge sort is stable and predictable, quick sort is fast in practice once the pivot avoids the worst case:

```js
function mergeSort(a) {
  if (a.length < 2) return a;
  const mid = a.length >> 1;
  const left = mergeSort(a.slice(0, mid)), right = mergeSort(a.slice(mid));
  const out = [];
  while (left.length && right.length) out.push(left[0] <= right[0] ? left.shift() : right.shift());
  return [...out, ...left, ...right];
}
console.log(mergeSort([3, 1, 4, 1, 5, 9, 2, 6]));   // [ 1, 1, 2, 3, 4, 5, 6, 9 ]

function quickSort(a) {
  if (a.length < 2) return a;
  const pivot = a[a.length >> 1];
  const less = a.filter((x) => x < pivot), eq = a.filter((x) => x === pivot), more = a.filter((x) => x > pivot);
  return [...quickSort(less), ...eq, ...quickSort(more)];
}
console.log(quickSort([3, 1, 4, 1, 5]));   // [ 1, 1, 3, 4, 5 ]
```

Binary search depends only on the sorted invariant, and getting the midpoint and bounds right is the whole trick:

```js
function binarySearch(sorted, target) {
  let lo = 0, hi = sorted.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (sorted[mid] === target) return mid;
    if (sorted[mid] < target) lo = mid + 1; else hi = mid - 1;
  }
  return -1;
}
function lowerBound(sorted, target) {
  let lo = 0, hi = sorted.length;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (sorted[mid] < target) lo = mid + 1; else hi = mid;
  }
  return lo;   // first index that is >= target
}
const sorted = [1, 3, 3, 5, 8];
console.log(binarySearch(sorted, 5), lowerBound(sorted, 3));   // 3 1
```

Recursion and Dynamic Programming:
Naive recursion recomputes the same subproblems; memoisation caches by argument so each is solved once:

```js
const fib = (n) => (n < 2 ? n : fib(n - 1) + fib(n - 2));

function memo(fn, cache = new Map()) {
  return function (...args) {
    const key = JSON.stringify(args);
    if (!cache.has(key)) cache.set(key, fn.apply(this, args));
    return cache.get(key);
  };
}
const fastFib = memo((n) => (n < 2 ? n : fastFib(n - 1) + fastFib(n - 2)));
console.log(fib(20), fastFib(90));   // 6765 2880067194370816120
```

Tabulation turns the recursion inside out and removes the call-stack limit entirely:

```js
function fibTable(n) {
  let prev = 0, cur = 1;
  for (let i = 0; i < n; i++) [prev, cur] = [cur, prev + cur];
  return prev;
}
console.log(fibTable(90));   // 2880067194370816120

function makeChange(coins, amount) {
  const dp = new Array(amount + 1).fill(Infinity);
  dp[0] = 0;
  for (let total = 1; total <= amount; total++) {
    for (const coin of coins) {
      if (coin <= total) dp[total] = Math.min(dp[total], dp[total - coin] + 1);
    }
  }
  return dp[amount] === Infinity ? -1 : dp[amount];
}
console.log(makeChange([1, 5, 10, 25], 63));   // 6
```

The 0/1 knapsack chooses a subset under a weight limit, with one row per item and one column per capacity:

```js
function knapsack(items, capacity) {
  const dp = Array.from({ length: items.length + 1 }, () => new Array(capacity + 1).fill(0));
  for (let i = 1; i <= items.length; i++) {
    const { weight, value } = items[i - 1];
    for (let c = 0; c <= capacity; c++) {
      dp[i][c] = dp[i - 1][c];
      if (weight <= c) dp[i][c] = Math.max(dp[i][c], dp[i - 1][c - weight] + value);
    }
  }
  return dp[items.length][capacity];
}
console.log(knapsack([
  { weight: 1, value: 1 }, { weight: 3, value: 4 }, { weight: 4, value: 5 }, { weight: 5, value: 7 },
], 7));   // 9
```

Longest common subsequence and edit distance differ only in their cost model, and both are two-dimensional:

```js
function lcs(a, b) {
  const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      dp[i][j] = a[i - 1] === b[j - 1]
        ? dp[i - 1][j - 1] + 1
        : Math.max(dp[i - 1][j], dp[i][j - 1]);
    }
  }
  return dp[a.length][b.length];
}
console.log(lcs('AGGTAB', 'GXTXAYB'));   // 4

function editDistance(a, b) {
  const dp = Array.from({ length: a.length + 1 }, (_, i) => [i, ...new Array(b.length).fill(0)]);
  for (let j = 0; j <= b.length; j++) dp[0][j] = j;
  for (let i = 1; i <= a.length; i++) {
    for (let j = 1; j <= b.length; j++) {
      dp[i][j] = a[i - 1] === b[j - 1]
        ? dp[i - 1][j - 1]
        : 1 + Math.min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]);
    }
  }
  return dp[a.length][b.length];
}
console.log(editDistance('kitten', 'sitting'));   // 3
```
